  // This strategy tracks two pieces of state: the already emitted output `generated`
  // and the currently active parser-constrained suffix `currentConstrained`.
  // On every step, it uses constrained decoding so the active suffix remains a valid
  // parser prefix for the target format, which is intended to support step-by-step
  // math solutions with arithmetic enclosed in << >>. The strategy simply keeps
  // extending the constrained suffix until EOS or the step budget is reached, and
  // mirrors accepted non-EOS tokens into `generated`. A separate loop counter `steps`
  // is maintained so the verifier can prove both `|generated| <= maxSteps` and
  // `cost <= maxSteps`.
  // CSD_RATIONALE_END
  var helpers := new CSDHelpers();
  var currentConstrained: Prefix := [];
  var steps: nat := 0;
  generated := [];
  while steps < maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant parser.IsValidPrefix(currentConstrained)
    invariant generated == currentConstrained
    invariant |generated| == steps
    invariant steps <= maxSteps
    invariant helpers.cost == steps
    decreases maxSteps - steps
  {
    if parser.IsCompletePrefix(currentConstrained) {
      break;
    } else {
      var next := helpers.ConstrainedStep(lm, parser, prompt, currentConstrained, eosToken);
      if next == eosToken {
        break;
